//! Per-agent bearer token authentication.
//!
//! Tokens are high-entropy random strings generated by
//! `threatfalcon-server token add`. Only their SHA-256 digests are stored in
//! the config file; a presented token is hashed and compared in constant
//! time against every configured digest.

use std::sync::Arc;

use anyhow::{anyhow, Result};
use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

use crate::config::AgentEntry;

/// Prefix that makes ThreatFalcon tokens recognisable (e.g. by secret
/// scanners) when they leak into logs or repositories.
pub const TOKEN_PREFIX: &str = "tfs_";
const TOKEN_RANDOM_BYTES: usize = 32;
const MAX_TOKEN_LEN: usize = 512;

/// Generate a new random agent token (`tfs_` + 64 hex characters).
pub fn generate_token() -> Result<String> {
    let mut buf = [0u8; TOKEN_RANDOM_BYTES];
    getrandom::fill(&mut buf).map_err(|e| anyhow!("failed to obtain random bytes: {e}"))?;
    Ok(format!("{TOKEN_PREFIX}{}", hex_encode(&buf)))
}

pub fn token_digest(token: &str) -> [u8; 32] {
    Sha256::digest(token.as_bytes()).into()
}

/// Lowercase hex SHA-256 of a token, as stored in `token_sha256`.
pub fn token_sha256_hex(token: &str) -> String {
    hex_encode(&token_digest(token))
}

pub fn hex_encode(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0x0f) as usize] as char);
    }
    out
}

fn hex_decode_32(s: &str) -> Option<[u8; 32]> {
    fn nibble(c: u8) -> Option<u8> {
        match c {
            b'0'..=b'9' => Some(c - b'0'),
            b'a'..=b'f' => Some(c - b'a' + 10),
            _ => None,
        }
    }
    let bytes = s.as_bytes();
    if bytes.len() != 64 {
        return None;
    }
    let mut out = [0u8; 32];
    for (i, pair) in bytes.chunks_exact(2).enumerate() {
        out[i] = (nibble(pair[0])? << 4) | nibble(pair[1])?;
    }
    Some(out)
}

/// Extract the token from an `Authorization: Bearer <token>` header value.
pub fn bearer_token(header_value: &str) -> Option<&str> {
    let (scheme, rest) = header_value.trim().split_once(' ')?;
    if !scheme.eq_ignore_ascii_case("bearer") {
        return None;
    }
    let token = rest.trim();
    if token.is_empty()
        || token.len() > MAX_TOKEN_LEN
        || !token.bytes().all(|b| b.is_ascii_graphic())
    {
        return None;
    }
    Some(token)
}

/// Digest → agent name lookup table built from the config.
#[derive(Debug, Clone, Default)]
pub struct TokenTable {
    entries: Vec<([u8; 32], Arc<str>)>,
}

impl TokenTable {
    pub fn new(agents: &[AgentEntry]) -> Result<Self> {
        let entries = agents
            .iter()
            .map(|a| {
                hex_decode_32(&a.token_sha256)
                    .map(|digest| (digest, Arc::<str>::from(a.name.as_str())))
                    .ok_or_else(|| anyhow!("agent {:?}: invalid token_sha256", a.name))
            })
            .collect::<Result<Vec<_>>>()?;
        Ok(Self { entries })
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Return the agent name for a presented token. Every entry is
    /// compared so the time taken does not depend on which one matches.
    pub fn verify(&self, token: &str) -> Option<Arc<str>> {
        let digest = token_digest(token);
        let mut found = None;
        for (candidate, name) in &self.entries {
            if bool::from(candidate.ct_eq(&digest)) {
                found = Some(name.clone());
            }
        }
        found
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sha256_known_vector() {
        assert_eq!(
            token_sha256_hex("abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
    }

    #[test]
    fn generated_tokens_are_prefixed_random_hex() {
        let a = generate_token().unwrap();
        let b = generate_token().unwrap();
        assert_ne!(a, b);
        assert!(a.starts_with(TOKEN_PREFIX));
        let hex = &a[TOKEN_PREFIX.len()..];
        assert_eq!(hex.len(), 64);
        assert!(hex
            .bytes()
            .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
        assert!(bearer_token(&format!("Bearer {a}")).is_some());
    }

    #[test]
    fn hex_round_trip() {
        let digest = token_digest("token");
        assert_eq!(hex_decode_32(&hex_encode(&digest)), Some(digest));
        assert_eq!(hex_decode_32("zz"), None);
        assert_eq!(hex_decode_32(&"A".repeat(64)), None);
    }

    #[test]
    fn parses_bearer_header() {
        assert_eq!(bearer_token("Bearer abc"), Some("abc"));
        assert_eq!(bearer_token("bearer abc"), Some("abc"));
        assert_eq!(bearer_token("BEARER   abc  "), Some("abc"));
        assert_eq!(bearer_token("Basic abc"), None);
        assert_eq!(bearer_token("Bearer"), None);
        assert_eq!(bearer_token("Bearer "), None);
        assert_eq!(bearer_token("Bearer a b"), None);
        assert_eq!(bearer_token("Bearerabc"), None);
        assert_eq!(bearer_token(&format!("Bearer {}", "a".repeat(513))), None);
    }

    #[test]
    fn verifies_tokens_against_table() {
        let agents = vec![
            AgentEntry {
                name: "one".into(),
                token_sha256: token_sha256_hex("tfs_one"),
            },
            AgentEntry {
                name: "two".into(),
                token_sha256: token_sha256_hex("tfs_two"),
            },
        ];
        let table = TokenTable::new(&agents).unwrap();
        assert_eq!(table.len(), 2);
        assert_eq!(table.verify("tfs_one").as_deref(), Some("one"));
        assert_eq!(table.verify("tfs_two").as_deref(), Some("two"));
        assert_eq!(table.verify("tfs_three"), None);
        assert_eq!(table.verify(""), None);
    }
}
